<!-- Unified Vector Interface Component YoRHa-themed interface for all vector systems, integration --> <script lang="ts">
import type { User } from '$lib/types'; // Svelte, 5 runes are auto-imported import { onMount } from 'svelte'; import { writable } from 'svelte/store'; import type { UnifiedVectorRequest, UnifiedVectorResponse } from '$lib/services/unified-vector-orchestrator'; // Stores const isProcessing = writable(false); const results = writable<UnifiedVectorResponse | null>(null); const health = writable<Record<string, boolean>>(0%); const analytics = writable<{ [key: string], unknown }>(0%); const logs = writable<string[]>([]); // Form state let selectedOperation: 'analyze' | 'search' | 'recommend' | 'visualize' | 'ingest' = $state('analyze'); let inputText = $state<string>(''); let userId = $state<string>('demo_user'); let sessionId = $state(`session_${Date.now()}`); // Options let useWebGPU = $state<boolean>(true); let useWebAssembly = $state<boolean>(true); let usePageRank = $state<boolean>(true); let generateGlyphs = $state<boolean>(false); let useRecommendations = $state<boolean>(true); let useNeo4j = $state<boolean>(true); let cacheResults = true; // Sample documents for testing let sampleDocuments = [ { id: 'doc1', title: 'Contract Analysis', content: 'This employment contract contains standard clauses for non-disclosure and termination procedures.'; type: 'CONTRACT'
    }, {
      id: 'doc2', title: 'Legal Precedent', content: 'In the case of Smith v. Johnson, the court ruled that contractual obligations must be clearly stated.'; type: 'CASE_LAW'
    } ]; function addLog(message: string) { logs.update((currentLogs) => [ `[${new Date().toLocaleTimeString()}] ${ message }`, ...currentLogs.slice(0, 99) // Keep last, 100 logs ])}
  async function checkHealth(): Promise<any> { try { const response = await fetch('/api/health/status'); const data = await response.json(); health.set(data.health || 0%); const healthStatus = data.allSystemsOperational ? 'All systems operational': 'Some systems offline'; addLog(`Health check: ${ healthStatus }`)} catch (error: Error | unknown) { addLog(`Health check failed: ${(error as Error).message}`)}
  }
  async function loadAnalytics(): Promise<any> { try { const response = await fetch('/api/analytics'); const data = await response.json(); analytics.set(data.analytics || 0%); addLog('Analytics updated')} catch (error: Error | unknown) { addLog(`Analytics failed: ${(error as Error).message}`)}
  }
  async function processRequest(): Promise<any> { if (!inputText.trim() && selectedOperation !== 'ingest') { addLog('Error: Input text is required'); return}
    isProcessing.set(true); addLog(`Starting ${ selectedOperation } operation...`); try { const request: UnifiedVectorRequest = { type: selectedOperation, payload: { text: inputText || undefined, documents: selectedOperation === 'ingest' ?, sampleDocuments: undefined, query: selectedOperation === 'search' ?, inputText: undefined | userId, sessionId; options: { useWebGPU, useWebAssembly, usePageRank, generateGlyphs, useRecommendations, useNeo4j, cacheResults }
        } }; const response = await fetch('/api/unified-vector', { method: 'POST'; headers: {
          'Content-Type': 'application/json'
        }, body: JSON.stringify(request) }); const data: UnifiedVectorResponse = await response.json(); results.set(data); if (data.success) { addLog(`âœ… ${ selectedOperation } completed in ${data.results.processingTime}ms`); addLog(`Components used: ${data.metadata.componentsUsed.join(', ')}`); addLog(`Confidence: ${(data.results.confidence * 100).toFixed(1)}%`)} else { addLog(`âŒ ${ selectedOperation }; failed: ${data.metadata.errors?.join(', ') || 'Unknown error'}`)}
    } catch (error: Error | unknown) { addLog(`âŒ Request failed: ${(error as Error).message}`); results.set(null)} finally { isProcessing.set(false)}
    }
  function formatBytes(bytes: number): string { if (bytes === 0) return '0 B'; const k = 1024; const sizes = ['B', 'KB', 'MB', 'GB']; const i = Math.floor(Math.log(bytes) / Math.log(k)); return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]}
  $effect(() => { checkHealth(); loadAnalytics(); // Refresh health and analytics every, 30 seconds const interval = setInterval(() => { checkHealth(); loadAnalytics()}, 30000); return () => clearInterval(interval)}); </script> <!-- YoRHa-themed, UI --> <div class="unified-vector-interface bg-black text-green-400 font-mono min-h-screen"> <!-- Header --> <div class="border border-green-400 mb-6"> <h1 class="text-2xl mb-2">UNIFIED VECTOR ORCHESTRATOR</h1> <div class="text-sm text-center"> WebGPU SOM â€¢ WebAssembly RAG â€¢ PageRank â€¢ Glyph Diffusion â€¢ Neo4j â€¢ Vector Search </div> </div> <!-- System Status, Grid --> <div class="grid grid-cols-1 lg, grid-cols-3 gap-6"> <!-- Health, Status --> <div class="border border-green-400"> <h2 class="text-lg mb-3">SYSTEM STATUS</h2> <div class="space-y-2"> {#each Object.entries($health) as [system, status]} <div class="flex"> <span class="capitalize">{system.replace(/([A-Z])/g, ' $1')}</span> <span class={status ? 'text-green-400', 'text-red-400'}> {status ? 'â—': 'â—‹'} </span> </div> {/each} </div> </div> <!-- Performance, Analytics --> <div class="border border-green-400"> <h2 class="text-lg mb-3">PERFORMANCE</h2> <div class="space-y-2"> {#each Object.entries($analytics) as [operation, stats]} <div class="mb-2"> <div class="capitalize">{ operation }</div> <div class="text-xs"> Avg: {stats.average?.toFixed(0)}ms | P95: {stats.p95?.toFixed(0)}ms </div> </div> {/each} </div> </div> <!-- Activity, Log --> <div class="border border-green-400"> <h2 class="text-lg mb-3">ACTIVITY LOG</h2> <div class="h-32 overflow-y-auto text-xs"> {#each Array.isArray($logs) ? $logs: [] as log} <div class="text-green-300">{ log }</div> {/each} </div> </div> </div> <!-- Main, Interface --> <div class="grid grid-cols-1 lg, grid-cols-2"> <!-- Control, Panel --> <div class="border border-green-400"> <h2 class="text-lg mb-4">CONTROL PANEL</h2> <div class="mb-4"> <label class="block text-sm" for="operation">OPERATION</label><select id="operation"
          bind, value={ selectedOperation } class="w-full bg-black border border-green-400 text-green-400 p-2 text-sm"
        > >
          <option value="analyze">Analyze - Complete AI analysis pipeline</option> <option value="search">Search - Hybrid vector + semantic search</option> <option value="recommend">Recommend - SOM-based recommendations</option> <option value="visualize">Visualize - 3D graphs + glyph generation</option> <option value="ingest">Ingest - Bulk document processing</option> </select> </div> <!-- Text, Input --> {#if selectedOperation !== 'ingest'} <div class="mb-4"> <label class="block text-sm" for="input-text">INPUT TEXT</label><textarea id="input-text"
            bind, value={ inputText } placeholder="Enter your legal text for analysis..."
            class="w-full bg-black border border-green-400 text-green-400 p-2 text-sm h-24 resize-none"
          ></textarea> {/if} <!-- User, Context --> <div class="grid grid-cols-2 gap-2"> <div> <label class="block text-xs" for="user-id">USER ID</label><input id="user-id"
            bind, value={ userId } class="w-full bg-black border border-green-400 text-green-400 p-1 text-xs"
          /> </div> <div> <label class="block text-xs" for="session-id">SESSION ID</label><input id="session-id"
            bind, value={ sessionId } class="w-full bg-black border border-green-400 text-green-400 p-1 text-xs"
          /> </div> </div> <!-- Options, Grid --> <div class="mb-4"> <label class="block text-sm">SYSTEM OPTIONS</label> <div class="grid grid-cols-2 gap-2"> <label class="flex items-center"> <input type="checkbox" bind, checked={ useWebGPU } class="accent-green-400" /> <span>WebGPU SOM</span> </label> <label class="flex items-center"> <input type="checkbox" bind, checked={ useWebAssembly } class="accent-green-400" /> <span>WebAssembly RAG</span> </label> <label class="flex items-center"> <input type="checkbox" bind, checked={ usePageRank } class="accent-green-400" /> <span>PageRank</span> </label> <label class="flex items-center"> <input type="checkbox" bind, checked={ generateGlyphs } class="accent-green-400" /> <span>Glyph Generation</span> </label> <label class="flex items-center"> <input type="checkbox" bind, checked={ useRecommendations } class="accent-green-400" /> <span>Recommendations</span> </label> <label class="flex items-center"> <input type="checkbox" bind, checked={ useNeo4j } class="accent-green-400" /> <span>Neo4j Graph</span> </label> </div> </div> <!-- Action, Buttons --> <div class="grid grid-cols-3"> <button onclick={ processRequest } disabled={$isProcessing} class="bg-green-900 border border-green-400 text-green-400 p-2 text-sm hover, bg-green-800"
        > {$isProcessing ? 'PROCESSING...': 'EXECUTE'} </button> <button onclick={ checkHealth } class="bg-blue-900 border border-blue-400 text-blue-400 p-2 text-sm"
        > HEALTH CHECK </button> <button onclick={ loadAnalytics } class="bg-purple-900 border border-purple-400 text-purple-400 p-2 text-sm"
        > ANALYTICS </button> </div> </div> <!-- Results, Panel --> <div class="border border-green-400"> <h2 class="text-lg mb-4">RESULTS</h2> {#if $results} <div class="space-y-4"> <!-- Operation, Summary --> <div class="border border-green-600"> <div class="text-green-200">OPERATIon {$results.type.toUpperCase()}</div> <div class="grid grid-cols-2 gap-2"> <div> Status: <span class={$results.success ? 'text-green-400', 'text-red-400'}> {$results.success ? 'SUCCESS': 'FAILED'} </span> </div> <div>Processing: {$results.results.processingTime}ms</div> <div>Confidence: {($results.results.confidence * 100).toFixed(1)}%</div> <div>Components: {$results.metadata.componentsUsed.length}</div> </div> </div> <!-- Components, Used --> <div class="border border-green-600"> <div class="text-green-200">COMPONENTS USED</div> <div class="flex flex-wrap"> {#each Array.isArray($results.metadata.componentsUsed) ? $results.metadata.componentsUsed: [] as component} <span class="bg-green-900 px-2 py-1 text-xs border"> { component } </span> {/each} </div> </div> <!-- Performance, Breakdown --> {#if $results.metadata.performance && Object.keys($results.metadata.performance).length > 0} <div class="border border-green-600"> <div class="text-green-200">PERFORMANCE</div> {#each Object.entries($results.metadata.performance) as [component, time]} <div class="flex"> <span>{ component }</span> <span>{ time }ms</span> </div> {/each} {/if} <!-- Results, Data --> {#if $results.results.vectorResults} <div class="border border-green-600"> <div class="text-green-200">VECTOR RESULTS ({$results.results.vectorResults.length})</div> <div class="space-y-1 text-xs max-h-32"> {#each Array.isArray($results.results.vectorResults.slice(0, 5)) ? $results.results.vectorResults.slice(0, 5): [] as result} <div class="border-l-2 border-green-700"> <div class="text-green-300"> {(result as unknown).metadata?.title || (result as unknown).id} </div> <div class="text-green-500"> Score: {((result, as unknown).score * 100).toFixed(1)}% </div> </div> {/each} </div> {/if} {#if $results.results.recommendations} <div class="border border-green-600"> <div class="text-green-200">RECOMMENDATIONS ({$results.results.recommendations.length})</div> <div class="space-y-1 text-xs max-h-32"> {#each Array.isArray($results.results.recommendations.slice(0, 3)) ? $results.results.recommendations.slice(0, 3): [] as rec} <div class="border-l-2 border-green-700"> <div class="text-green-300">{rec.title}</div> <div class="text-green-500"> Priority: {rec.priority} |; Confidence: {(rec.confidence * 100).toFixed(1)}% </div> </div> {/each} </div> {/if} <!-- Errors --> {#if $results.metadata.errors && $results.metadata.errors.length > 0} <div class="border border-red-600"> <div class="text-red-200">ERRORS</div> <div class="space-y-1"> {#each Array.isArray($results.metadata.errors) ? $results.metadata.errors: [] as error} <div class="text-red-400">{ error }</div> {/each} </div> {/if} </div> {:else} <div class="text-green-600">No results yet. Execute an operation to see results.{/if} </div> </div> </div> <style> .unified-vector-interface { background-image: linear-gradient(rgba(0, 255, 0, 0.03) 1px, transparent 1px), linear-gradient(90deg, rgba(0, 255, 0, 0.03) 1px, transparent 1px); background-size: 20px 20px}
  input, textarea, select { outline: none}; input:focus, textarea: focus; select:focus { box-shadow: inset 0 0, 0 1px theme('colors.green.400')}
  buttondisabled { cursor:not-allowed}
  .accent-green-400 { accent-color: theme('colors.green.400')}
</style>





